 ICON.bmRecapEl=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><circle cx="40" cy="200" r="34" fill="#fff" stroke="${BLU}" stroke-width="5"/>${BM_T(40,208,'bio',{fs:22,fw:800,a:'middle',fill:BLU})}${BM_L(40,166,40,80,'#18213A',4)}${BM_L(40,80,90,80,'#18213A',4)}${BM_res(90,80,270,GRN,5)}${BM_L(270,80,340,80,'#18213A',4)}${`<g transform="rotate(90 340 80)">${BM_res(340,80,520,ORG,5)}</g>`}${BM_L(340,260,340,300,'#18213A',4)}${BM_L(40,234,40,300,'#18213A',4)}${BM_L(40,300,340,300,'#18213A',4)}${BM_T(180,46,'Z',{fs:30,fw:800,a:'middle',fill:GRN})}${BM_T(196,56,'e',{fs:20,fw:800,fill:GRN})}${BM_T(364,180,'Z',{fs:30,fw:800,fill:ORG})}${BM_T(384,190,'in',{fs:20,fw:800,fill:ORG})}</g>`;
 ICON.bmRecapBr=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><polygon points="210,20 360,165 210,310 60,165" fill="none" stroke="#18213A" stroke-width="5"/><polygon points="285,61 316,92 285,123 254,92" fill="#FFFFFF" stroke="${ORG}" stroke-width="6"/>${[[135,92],[135,238],[285,238]].map(([a,q])=>`<polygon points="${a},${q-31} ${a+31},${q} ${a},${q+31} ${a-31},${q}" fill="#FFFFFF" stroke="${INK}" stroke-width="5"/>`).join('')}${BM_T(210,175,'ΔV',{fs:30,fw:800,a:'middle',fill:BLU})}${BM_T(330,70,'gauge',{fs:22,fw:800,fill:ORG})}</g>`;
